from typing import Tuple
Matrix = Tuple[Tuple[int, ...], ...]
Poly = Tuple[int, ...]

def inv_mod(a: int, p: int) -> int:
    return pow(a % p, p - 2, p)

def mat_mul(a: Matrix, b: Matrix, p: int) -> Matrix:
    n, m, k = len(a), len(b[0]), len(b)
    return tuple(tuple(sum(a[i][t] * b[t][j] for t in range(k)) % p
                       for j in range(m)) for i in range(n))

def charpoly(a: Matrix, p: int) -> Poly:
    n = len(a)
    M = tuple(tuple(0 for _ in range(n)) for _ in range(n))
    coeffs = [0] * (n + 1); coeffs[n] = 1
    for k in range(1, n + 1):
        AM = mat_mul(a, M, p)
        c_prev = coeffs[n - k + 1]
        M = tuple(tuple((AM[i][j] + (c_prev if i == j else 0)) % p
                        for j in range(n)) for i in range(n))
        trace = sum(mat_mul(a, M, p)[i][i] for i in range(n)) % p
        coeffs[n - k] = (-inv_mod(k, p) * trace) % p
    return tuple(coeffs)

from typing import Set, Tuple
Poly = Tuple[int, ...]

def poly_pow_mod(base: Poly, e: int, m: Poly, p: int) -> Poly:
    result: Poly = (1,)
    while e:
        if e & 1:
            result = _mulmod(result, base, m, p)
        base = _mulmod(base, base, m, p)
        e >>= 1
    return result

def is_irreducible(f: Poly, p: int) -> bool:
    f = _trim(f, p); d = len(f) - 1
    if d <= 0: return False
    if d == 1: return True
    x: Poly = (0, 1)
    if _trim(_sub(poly_pow_mod(x, p ** d, f, p), x), p) != (0,):
        return False
    for q in _prime_divisors(d):
        h = poly_pow_mod(x, p ** (d // q), f, p)
        if len(_gcd(_sub(h, x), f, p)) - 1 != 0:
            return False
    return True
# helpers _mulmod, _trim, _sub, _gcd, _prime_divisors: see demo.py

