function MINPOLY_DEGREE(A, p):
    powers <- [I]
    basis  <- [flatten(I)]
    loop:
        P <- A * powers.last      (mod p)
        if rank(basis + [flatten(P)]) does not increase:
            return len(powers) - 1
        powers.append(P); basis.append(flatten(P))

function IS_REGULAR_TORAL(A, p):
    return MINPOLY_DEGREE(A, p) == dim(A)

function EXPANSION(G, S):
    best <- +inf
    for each nonempty A subset of G with 2*|A| <= |G|:
        N    <- { a*s : a in A, s in S }
        bdry <- N \ A
        best <- min(best, |bdry| / |A|)
    return best

